}
.place-card__media { height: 180px; background: #4338ca; }
.place-card__body { /* 여백 */ }

problems.answer:
.place-card {
  width: 240px;
  border: 1px solid #625b70;
  border-radius: 12px;
  overflow: hidden;
  background: #211d29;
}
.place-card__media { height: 180px; background: #4338ca; }
