problems.starterCode:
.plan-card { display: flex; flex-direction: column; width: 300px; }
.plan-card ul { list-style: none; padding: 0; }
.plan-card li { /* 행 구분 */ }
.plan-cta { margin-top: auto; }
.plan-cta:hover { /* 상태 */ }
.plan-cta:focus-visible { /* 포커스 */ }

problems.answer:
.plan-card { display: flex; flex-direction: column; width: 300px; min-height: 340px; border: 1px solid #625b70; border-radius: 12px; overflow: hidden; }
.plan-card header { padding: 20px; background: #312e81; }
.plan-card ul { list-style: none; padding: 0; margin: 0; }
.plan-card li { padding: 12px 20px; border-bottom: 1px solid #4c4657; }
.plan-cta { margin: auto 20px 20px; padding: 12px; border: 0; background: #7c3aed; color: white; }
.plan-cta:hover { background: #6d28d9; }
.plan-cta:focus-visible { outline: 3px solid #c4b5fd; outline-offset: 3px; }

problems.starterCode:
.social-card { width: 375px; }
.social-card header,
.social-actions,
.social-card form { /* 행 정렬 */ }
.social-media { height: 260px; background: #3730a3; }
.save { /* 오른쪽으로 */ }

problems.answer:
.social-card { width: 375px; border: 1px solid #625b70; border-radius: 12px; overflow: hidden; }
.social-card header, .social-actions, .social-card form { display: flex; align-items: center; gap: 10px; padding: 12px; }
.avatar { width: 36px; height: 36px; border-radius: 50%; background: #a78bfa; }
.social-card header strong { flex: 1; }
.social-media { height: 260px; background: #3730a3; }
.save { margin-left: auto; }
.social-card p { padding-inline: 12px; }
.social-card form input { flex: 1; min-width: 0; }

problems.starterCode:
.profile-card { width: 400px; }
.profile-card header { display: flex; align-items: center; gap: 16px; }
.profile-gallery { display: grid; /* 4열 */ }
.profile-gallery span { /* 정사각형 */ }

problems.answer:
.profile-card { width: 400px; border: 1px solid #625b70; border-radius: 16px; overflow: hidden; }
.profile-card header { display: flex; align-items: center; gap: 16px; padding: 20px; }
.profile-avatar { width: 64px; height: 64px; border-radius: 50%; background: #7c3aed; }
.profile-gallery { display: grid; grid-template-columns: repeat(4, 1fr); gap: 2px; }
.profile-gallery span { aspect-ratio: 1; background: #3730a3; }
.profile-gallery span:nth-child(even) { background: #5b21b6; }

problems.starterCode:
.bookmark-card { position: relative; width: 250px; }
.bookmark-button { position: absolute; top: 12px; right: 12px; }

/* hover와 focus-visible 상태를 작성하세요 */

problems.answer:
.bookmark-card { position: relative; width: 250px; padding: 12px; border-radius: 14px; background: #211d29; }
.bookmark-media { height: 220px; border-radius: 10px; background: #312e81; }
.bookmark-button { position: absolute; top: 22px; right: 22px; width: 44px; height: 44px; border-radius: 50%; }
.bookmark-card:hover .bookmark-button, .bookmark-button:focus-visible { transform: scale(1.08); background: #7c3aed; color: white; }
.bookmark-button:focus-visible { outline: 3px solid #c4b5fd; outline-offset: 3px; }

problems.starterCode:
.search-shell { min-height: 100vh; display: grid; /* 행 */ }
.search-shell header { /* 양끝 */ }
.search-shell main { /* 중앙 */ }
.search-form { display: flex; }
.search-input:focus-visible { /* 포커스 */ }

problems.answer:
.search-shell { min-height: 100vh; display: grid; grid-template-rows: auto 1fr auto; }
.search-shell header { display: flex; justify-content: space-between; align-items: center; padding: 16px 24px; }
.search-shell main { display: grid; place-content: center; gap: 20px; padding: 24px; text-align: center; }
.search-form { display: flex; width: min(560px, 100%); gap: 8px; }
.search-input { flex: 1; min-width: 0; }
.search-input:focus-visible { outline: 3px solid #a78bfa; outline-offset: 3px; }
.search-shell footer { padding: 16px 24px; border-top: 1px solid #4c4657; }

.trip-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 20px; }
.trip-card { padding: 12px; border: 1px solid #625b70; border-radius: 12px; }
.trip-media { aspect-ratio: 16 / 9; border-radius: 8px; background: #3730a3; }
@media (max-width: 900px) { .trip-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
@media (max-width: 600px) { .trip-grid { grid-template-columns: 1fr; } }

problems.starterCode:
.room-gallery { display: grid; gap: 12px; }
.room-gallery .featured { /* 두 열 */ }
/* 태블릿과 모바일 열을 작성하세요 */

problems.answer:
.room-gallery { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); grid-auto-rows: 180px; gap: 12px; }
.room-gallery article { display: grid; place-items: center; background: #312e81; }
.room-gallery .featured { grid-column: span 2; }
@media (max-width: 900px) { .room-gallery { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
@media (max-width: 560px) { .room-gallery { grid-template-columns: 1fr; } .room-gallery .featured { grid-column: span 1; } }

problems.starterCode:
.chat-shell { width: min(375px, 100%); height: 700px; display: flex; flex-direction: column; }
.messages { /* 남은 공간과 스크롤 */ }
.message { /* 말풍선 */ }
.message--mine { /* 오른쪽 */ }
.composer { display: flex; }

problems.answer:
.chat-shell { width: min(375px, 100%); height: 700px; display: flex; flex-direction: column; border: 1px solid #625b70; border-radius: 16px; overflow: hidden; }
.chat-shell header, .composer { display: flex; align-items: center; gap: 10px; padding: 12px; }
.chat-shell header strong { flex: 1; }
.messages { flex: 1; min-height: 0; overflow-y: auto; display: flex; flex-direction: column; gap: 10px; padding: 12px; }
.message { align-self: flex-start; max-width: 78%; padding: 10px 12px; border-radius: 12px; background: #312e81; }
.message--mine { align-self: flex-end; background: #6d28d9; }
.composer input { flex: 1; min-width: 0; }

problems.starterCode:
.product-grid { display: grid; gap: 20px; }
.product-card { padding: 12px; }
/* 4→2→1열과 상태를 완성하세요 */

problems.answer:
.product-grid { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 20px; }
.product-card { padding: 12px; border: 1px solid #625b70; border-radius: 12px; }
.product-media { aspect-ratio: 4 / 3; border-radius: 8px; background: #3730a3; }
.product-card:hover { transform: translateY(-4px); }
.product-card a:focus-visible { outline: 3px solid #a78bfa; outline-offset: 3px; }
@media (max-width: 900px) { .product-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
@media (max-width: 560px) { .product-grid { grid-template-columns: 1fr; } }
